/** @module steward/app
 * @description Steward console browser flow and support views.
 */
import { createPortalAuth } from '/static/auth.js?v=0.5.15';
let auth=null,authBootstrap=null,entryAttempt=null,consoleReady=false;
const signOut = document.querySelector('#sign-out');
if (['localhost','127.0.0.1'].includes(location.hostname)) document.querySelector('[data-steward-home]')?.setAttribute('href','/stewards');
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=(v)=>v?new Intl.DateTimeFormat('en-CA',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—';
const money=(v,c='USD')=>new Intl.NumberFormat('en-US',{style:'currency',currency:c}).format((v??0)/100);
const H={'content-type':'application/json'};
const routeBase=['localhost','127.0.0.1'].includes(location.hostname)?'/stewards':'';
const routes={dashboard:'/',accounts:'/accounts/',transactions:'/transactions/',closures:'/scheduled-closures/',refunds:'/refunds/','email-suppressions':'/email-block-list/',manager:'/steward-manager/'};
const state={view:'dashboard',dashboard:null,account:null,transaction:null,closures:[],refunds:[],emailSuppressions:[],emailSuppressionQuery:'',accountMatches:[],accountSearch:{first:'',last:'',name:''},manager:null,selectedStaff:null,staffActivity:[],staffActivityNext:null,editWatcher:null,stewardRole:null,sensitiveOpenedAt:0,lastActivity:Date.now()};
let dialogReturnFocus=null;
let idleWarning=null;
let cancelStaffConfirmation=null;
const IDLE_LIMIT_MS=30*60*1000;
const IDLE_WARNING_MS=2*60*1000;
function syncAuthChrome(){for(const button of [signOut,$('#shell-sign-out')].filter(Boolean)){button.hidden=!auth?.authenticated;button.onclick=()=>auth?.signOut();}}
async function portalAuth({reload=false}={}){if(auth&&!reload)return auth;if(authBootstrap)return authBootstrap;authBootstrap=createPortalAuth('steward').then(session=>{auth=session;syncAuthChrome();return session}).finally(()=>{authBootstrap=null});return authBootstrap;}
async function api(path,opt={}){const session=auth||await portalAuth();const r=await session.fetch(path,{...opt,headers:{...H,...opt.headers}});const b=await r.json().catch(()=>({}));if(!r.ok){const suffix=b.requestId?` Request ${b.requestId}.`:'';throw Object.assign(new Error(`${b.error||`Request failed (${r.status})`}${suffix}`),{status:r.status,requestId:b.requestId})}return b;}
function toast(m){const n=$('#toast');n.textContent=m;n.classList.remove('hidden');setTimeout(()=>n.classList.add('hidden'),3500)}
function clearFormErrors(form){if(!form)return;$$('[data-form-error]',form).forEach(node=>node.remove());}
function showFormError(form,message){if(!form?.isConnected){toast(message);return;}clearFormErrors(form);const summary=document.createElement('div');summary.className='notice error form-error-summary';summary.dataset.formError='';summary.tabIndex=-1;summary.setAttribute('role','alert');summary.textContent=message;form.prepend(summary);summary.focus();}
function associateStewardLabels(root=document){const copy=new Map([['Banned phrase','Trigger phrase'],['Screenshot pixels','Visual change'],['All-clear consensus','Approvals required to accept a new baseline'],['Alert-received consensus','Acknowledgements required'],['Pixel threshold (%)','Visual change threshold (%)']]);const inferred=new Map([['body','Operational note'],['reason','Staff reason'],['q','Lookup value']]);let index=0;$$('label',root).forEach((label)=>{const current=label.textContent.trim();if(copy.has(current)){const textNodes=[...label.childNodes].filter((node)=>node.nodeType===Node.TEXT_NODE);if(label.querySelector('input,select,textarea')&&textNodes.length)textNodes.at(-1).textContent=` ${copy.get(current)}`;else label.textContent=copy.get(current);}if(current==='Detection methods'&&label.nextElementSibling?.classList.contains('checks')){label.id||=`steward-group-${++index}`;label.nextElementSibling.setAttribute('role','group');label.nextElementSibling.setAttribute('aria-labelledby',label.id);return;}if(label.htmlFor||label.querySelector('input,select,textarea'))return;const control=label.nextElementSibling?.matches?.('input,select,textarea')?label.nextElementSibling:label.parentElement?.querySelector('input,select,textarea');if(!control)return;control.id||=`steward-field-${++index}`;label.htmlFor=control.id;});$$('input:not([type="hidden"]),select,textarea',root).forEach((control)=>{if(control.labels?.length||control.getAttribute('aria-label')||control.getAttribute('aria-labelledby'))return;control.id||=`steward-field-${++index}`;const label=document.createElement('label');label.htmlFor=control.id;label.textContent=inferred.get(control.name)||control.placeholder||control.name.replace(/([A-Z])/g,' $1').replace(/^./,(char)=>char.toUpperCase());control.before(label);});}
function enhanceStewardTables(root=document){$$('table',root).forEach((table)=>{const labels=$$('thead th',table).map((cell)=>cell.textContent.trim());table.classList.add('responsive-records');$$('tbody tr',table).forEach((row)=>$$('td',row).forEach((cell,index)=>cell.dataset.label=labels[index]||`Field ${index+1}`));});}
function dialogFocusable(root){return $$('a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),summary,[tabindex]:not([tabindex="-1"])',root).filter((node)=>!node.hidden&&node.getClientRects().length);}
function isolateDialog(modal){
  if(!dialogReturnFocus&&document.activeElement instanceof HTMLElement)dialogReturnFocus=document.activeElement;
  $('#steward-root')?.setAttribute('inert',''); $('.app-topbar')?.setAttribute('inert',''); document.body.classList.add('modal-open');
  requestAnimationFrame(()=>{const target=modal.querySelector('[data-modal-initial-focus]')||dialogFocusable(modal)[0]||modal;target.focus();});
}
function releaseDialog(){
  $('#steward-root')?.removeAttribute('inert'); $('.app-topbar')?.removeAttribute('inert'); document.body.classList.remove('modal-open');
  const returnTo=dialogReturnFocus; dialogReturnFocus=null;if(returnTo)requestAnimationFrame(()=>{const target=returnTo.isConnected?returnTo:$$('[data-action]').find(node=>node.dataset.action===returnTo.dataset.action&&node.dataset.id===returnTo.dataset.id&&node.dataset.email===returnTo.dataset.email);target?.focus();});
}
function prepareRenderedDialog(){const modal=$('#steward-root .modal');if(!modal){if(!document.querySelector('body > .modal'))releaseDialog();return;}modal.tabIndex=-1;document.body.append(modal);isolateDialog(modal);}
function routePath(view){return `${routeBase}${routes[view]||routes.dashboard}`||'/'}
function viewFromLocation(){let path=location.pathname;if(routeBase&&path.startsWith(routeBase))path=path.slice(routeBase.length)||'/';if(path==='/index.html')path='/';if(path!=='/'&&!path.endsWith('/'))path+='/';return Object.entries(routes).find(([,value])=>value===path)?.[0]||'dashboard'}
function routeUrl(view,params={}){const url=new URL(routePath(view),location.origin);for(const [key,value] of Object.entries(params))if(value!=null&&value!=='')url.searchParams.set(key,String(value));return `${url.pathname}${url.search}`}
function updateRoute(view,params={},replace=false){history[replace?'replaceState':'pushState']({view},'',routeUrl(view,params));updateRouteChrome()}
function updateRouteChrome(){const label={dashboard:'Global dashboard',accounts:'Client account lookup',transactions:'Transaction lookup',closures:'Account closures',refunds:'Refunds','email-suppressions':'Email block list',manager:'Steward Manager'}[state.view]||'Steward console';document.title=`${label} | CLOVERSIGHT Stewards`;const routeLabel=$('[data-route-label]');if(routeLabel)routeLabel.textContent=label;$$('[data-view]').forEach(button=>button.classList.toggle('active',button.dataset.view===state.view))}
function currentRouteParams(){if(state.view==='accounts'&&state.account?.account?.id)return {account:state.account.account.id};if(state.view==='transactions'&&state.transaction?.transaction?.id)return {transaction:state.transaction.transaction.id};return {}}
async function closeSupportDialog(){state.editWatcher=null;document.querySelector('body > .modal')?.remove();updateRoute('accounts',currentRouteParams(),true);await render();}
function requestStaffConfirmation({title,copy,amountMax=null,confirmLabel='Confirm action'}){
  cancelStaffConfirmation?.();
  return new Promise((resolve)=>{
    document.querySelector('body > .modal')?.remove();
    const modal=document.createElement('div');modal.className='modal';modal.setAttribute('role','dialog');modal.setAttribute('aria-modal','true');modal.setAttribute('aria-labelledby','staff-confirm-title');modal.tabIndex=-1;
    modal.innerHTML=`<form class="modal-panel staff-confirm-panel"><div class="staff-confirm-header"><p class="eyebrow">Steward confirmation</p><h2 id="staff-confirm-title">${esc(title)}</h2><p class="muted">${esc(copy)}</p></div><div class="staff-confirm-body">${amountMax==null?'':`<div class="field"><label for="staff-confirm-amount">Refund amount in cents</label><input id="staff-confirm-amount" name="amount" type="number" min="1" max="${Number(amountMax)}" value="${Number(amountMax)}" required></div>`}<div class="field"><label for="staff-confirm-reason">Staff reason</label><textarea id="staff-confirm-reason" name="reason" minlength="5" required data-modal-initial-focus aria-describedby="staff-confirm-help"></textarea><small id="staff-confirm-help">Use at least five characters. This reason is retained in the staff event history.</small></div></div><div class="form-actions"><button type="button" class="secondary" data-staff-cancel>Cancel</button><button class="danger">${esc(confirmLabel)}</button></div></form>`;
    let finished=false;
    const finish=(value)=>{if(finished)return;finished=true;if(cancelStaffConfirmation===cancel)cancelStaffConfirmation=null;modal.remove();releaseDialog();resolve(value);};
    const cancel=()=>finish(null);cancelStaffConfirmation=cancel;
    modal.querySelector('[data-staff-cancel]').onclick=()=>finish(null);
    modal.querySelector('form').onsubmit=(event)=>{event.preventDefault();const data=new FormData(event.currentTarget);const reason=String(data.get('reason')||'').trim();if(reason.length<5)return;const amount=amountMax==null?null:Number(data.get('amount'));if(amountMax!=null&&(!Number.isInteger(amount)||amount<1||amount>Number(amountMax)))return;finish({reason,amount});};
    document.body.append(modal);isolateDialog(modal);
  });
}
const wait=milliseconds=>new Promise(resolve=>setTimeout(resolve,milliseconds));
function showEntryError(error){const errorBox=$('#entry-error');if(errorBox){errorBox.textContent=`Unable to open steward console: ${error.message}`;errorBox.classList.remove('hidden')}toast(`Unable to open steward console: ${error.message}`)}
async function loadDashboardWithRetry(){const delays=[0,300,900];let lastError;for(const delay of delays){if(delay)await wait(delay);try{return await api('/api/steward/dashboard')}catch(error){lastError=error;const retryable=!error.status||error.status===401||error.status===429||error.status>=500;if(!retryable)throw error;if(error.status===401)await portalAuth({reload:true})}}throw lastError}
async function enterStewardConsole({interactive=false}={}){if(entryAttempt)return entryAttempt;entryAttempt=(async()=>{const button=$('#enter');if(button){button.disabled=true;button.setAttribute('aria-busy','true')}$('#entry-error')?.classList.add('hidden');try{const session=await portalAuth({reload:Boolean(auth&&!auth.authenticated)});if(!session.authenticated){if(interactive)await session.signIn();return}state.dashboard=await loadDashboardWithRetry();state.stewardRole=state.dashboard.stewardRole;shell();consoleReady=true;await hydrateLocation()}catch(error){showEntryError(error)}finally{if(button){button.disabled=false;button.removeAttribute('aria-busy')}entryAttempt=null}})();return entryAttempt}
function stewardRailArt(){return `<div class="rail-signature" aria-hidden="true"><span class="rail-orbit"><svg class="orbit-svg rail-orbit-svg" viewBox="-16 -16 152 152" focusable="false"><defs><radialGradient id="steward-rail-planet-fill" cx="36%" cy="31%" r="72%"><stop offset="0" stop-color="#fffdfd"/><stop offset=".2" stop-color="#ffdaed"/><stop offset=".58" stop-color="#ee7cbc"/><stop offset="1" stop-color="#a70c68"/></radialGradient><radialGradient id="steward-rail-moon-fill" cx="34%" cy="30%" r="72%"><stop offset="0" stop-color="#fff8ce"/><stop offset=".38" stop-color="#f3c65a"/><stop offset=".74" stop-color="#ba7418"/><stop offset="1" stop-color="#71400d"/></radialGradient><clipPath id="steward-rail-back"><rect x="-16" y="-16" width="152" height="76"/></clipPath><clipPath id="steward-rail-front"><rect x="-16" y="60" width="152" height="76"/></clipPath><path id="steward-rail-path" d="M .5 60 A 59.5 22.5 0 1 1 119.5 60 A 59.5 22.5 0 1 1 .5 60"/></defs><g transform="rotate(-18 60 60)"><use class="orbit-ring-path" href="#steward-rail-path"/><g class="orbit-moon-motion orbit-moon-back-layer" clip-path="url(#steward-rail-back)"><circle class="orbit-moon" r="7" fill="url(#steward-rail-moon-fill)"><animateMotion begin="-1.875s" calcMode="linear" dur="7.5s" repeatCount="indefinite" rotate="0"><mpath href="#steward-rail-path"/></animateMotion></circle></g><g class="orbit-planet-art rail-planet-art"><circle class="orbit-planet" cx="60" cy="60" r="39" fill="url(#steward-rail-planet-fill)"/><circle class="orbit-planet-glint" cx="48" cy="47" r="10"/></g><g class="orbit-moon-motion orbit-moon-front-layer" clip-path="url(#steward-rail-front)"><circle class="orbit-moon" r="7" fill="url(#steward-rail-moon-fill)"><animateMotion begin="-1.875s" calcMode="linear" dur="7.5s" repeatCount="indefinite" rotate="0"><mpath href="#steward-rail-path"/></animateMotion></circle></g><circle class="orbit-moon orbit-moon-static" cx="119.5" cy="60" r="7" fill="url(#steward-rail-moon-fill)"/></g></svg></span><p>Guard<br>what matters</p></div>`}
function shell(){const home=routeBase||'/';$('#entry-topbar').hidden=true;$('#steward-root').innerHTML=`<div class="app-layout"><aside class="app-rail"><a class="brand" href="${home}" aria-label="CLOVERSIGHT home"><span class="brand-images"><img class="brand-full brand-light" src="/static/brand/cloversight.svg?v=0.5.15" width="516" height="72" alt="CLOVERSIGHT"><img class="brand-full brand-dark" src="/static/brand/cloversight-dark.svg?v=0.5.15" width="516" height="72" alt=""><img class="brand-compact brand-light" src="/static/brand/cloversight-mark.svg?v=0.5.15" width="72" height="72" alt=""><img class="brand-compact brand-dark" src="/static/brand/cloversight-mark-dark.svg?v=0.5.15" width="72" height="72" alt=""></span></a><button id="steward-menu-toggle" class="portal-menu-toggle secondary" type="button" aria-expanded="false" aria-controls="steward-navigation" aria-label="Open steward console navigation"><span class="portal-menu-icon" aria-hidden="true"></span></button><nav id="steward-navigation" class="sidebar" aria-label="Steward console" data-open="false"><button data-view="dashboard" type="button"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 10.7 12 3l9 7.7v9.1c0 .7-.5 1.2-1.2 1.2H4.2C3.5 21 3 20.5 3 19.8z"/><path d="M9 21v-6h6v6"/></svg><span>Dashboard</span></button><button data-view="accounts" type="button"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="7" r="4"/><path d="M4 21v-2a6 6 0 0 1 6-6h4a6 6 0 0 1 6 6v2z"/></svg><span>Client accounts</span></button><button data-view="transactions" type="button"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 9h18M16 15h2"/></svg><span>Transactions</span></button><button data-view="closures" type="button"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 3h14v18H5zM8 8h8M8 12h8M8 16h5"/></svg><span>Account closures</span></button><button data-view="refunds" type="button"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 7H7a4 4 0 0 0 0 8h11M9 3 5 7l4 4"/><circle cx="18" cy="15" r="3"/></svg><span>Refunds</span></button><button data-view="email-suppressions" type="button"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m4 7 8 6 8-6M5 19 19 5"/></svg><span>Email block list</span></button>${state.stewardRole==='owner'?'<button data-view="manager" type="button"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="7" r="4"/><path d="M4 21v-2a6 6 0 0 1 6-6h4a6 6 0 0 1 6 6v2zM18 8h4M20 6v4"/></svg><span>Steward Manager</span></button>':''}</nav>${stewardRailArt()}</aside><section class="app-stage"><div class="app-stage-globe ww-regional" data-hero-globe aria-hidden="true" inert><div class="rg-stage"><div class="rg-spills"></div><div class="rg-host"></div><div class="rg-pin-label"></div><div class="rg-fallback" hidden></div></div><span hidden data-hero-region></span></div><header class="app-topbar"><div class="topbar-context"><span class="status-dot" aria-hidden="true"></span><span data-route-label>Steward console</span></div><div class="topbar-summary"><span class="badge pink">Staff only</span><span class="steward-identity">${esc(auth?.user?.email||'Authenticated steward')}</span></div><div class="actions"><button id="shell-sign-out" class="secondary sign-out" type="button">Sign out</button></div></header><main id="workspace" class="workspace"></main></section></div>`;syncAuthChrome();const menu=$('#steward-menu-toggle'),navigation=$('#steward-navigation');menu.onclick=()=>{const open=navigation.dataset.open!=='true';navigation.dataset.open=String(open);menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close steward console navigation':'Open steward console navigation')};$$('[data-view]').forEach(button=>button.onclick=()=>{navigation.dataset.open='false';menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open steward console navigation');void navigate(button.dataset.view)});updateRouteChrome()}
async function navigate(view,params={}){jettison();if(view==='accounts'){state.accountMatches=[];state.accountSearch={first:'',last:'',name:''}}if(view==='manager'&&state.stewardRole!=='owner')view='dashboard';state.view=view;updateRoute(view,params);try{await api('/api/steward/activity',{method:'POST',body:JSON.stringify({view})})}catch(error){toast(`Unable to record page visit: ${error.message}`)}await render()}
async function hydrateLocation(){const view=viewFromLocation(),query=new URLSearchParams(location.search);jettison();state.view=view==='manager'&&state.stewardRole!=='owner'?'dashboard':view;try{if(consoleReady)await api('/api/steward/activity',{method:'POST',body:JSON.stringify({view:state.view})});if(view==='accounts'&&query.get('account'))state.account=await api(`/api/steward/accounts/${encodeURIComponent(query.get('account'))}`);if(view==='transactions'&&query.get('transaction'))state.transaction=await api(`/api/steward/transactions/${encodeURIComponent(query.get('transaction'))}`);if(view==='email-suppressions')state.emailSuppressionQuery=String(query.get('q')||'').trim();if(view==='accounts'&&state.account&&query.get('modal')==='watcher-edit'&&query.get('watcher')){const watcher=state.account.watchers.find(item=>item.id===query.get('watcher'));if(watcher)state.editWatcher=structuredClone(watcher)}}catch(error){toast(`Unable to open the linked record: ${error.message}`)}await render()}
function head(t,c){return `<div class="workspace-header"><div><p class="eyebrow">Steward console</p><h1>${esc(t)}</h1><p class="muted">${esc(c)}</p></div></div>`}
function badge(s){const k=['active','completed','green'].includes(s)?'green':['failed','declined'].includes(s)?'red':['open','scheduled','acknowledged'].includes(s)?'pink':'amber';return `<span class="badge ${k}">${esc(String(s).replaceAll('_',' '))}</span>`}
async function render(){document.querySelector('body > .modal')?.remove();const w=$('#workspace');if(!w)return;w.tabIndex=-1;if(state.view==='dashboard'){if(!state.dashboard)state.dashboard=await api('/api/steward/dashboard');w.innerHTML=dashboard()}else if(state.view==='accounts')w.innerHTML=accountLookup();else if(state.view==='transactions')w.innerHTML=transactionLookup();else if(state.view==='closures'){state.closures=await api('/api/steward/closures');w.innerHTML=closureView()}else if(state.view==='refunds'){state.refunds=await api('/api/steward/refunds');w.innerHTML=refundView()}else if(state.view==='email-suppressions'){state.emailSuppressions=await api(`/api/steward/email-suppressions?q=${encodeURIComponent(state.emailSuppressionQuery)}`);w.innerHTML=emailSuppressionView()}else if(state.view==='manager'){state.manager=await api('/api/steward/manager');w.innerHTML=managerView()}updateRouteChrome();bind();associateStewardLabels(w);enhanceStewardTables(w);prepareRenderedDialog();checkIdleTimeout()}
function dashboard(){const d=state.dashboard;return `${head('Global dashboard','Operational shape without exposing customer content.')}<div class="metrics"><div class="metric"><strong>${d.accounts}</strong><span>Customer accounts</span></div><div class="metric"><strong>${d.activeWatchers}</strong><span>Active watchers</span></div><div class="metric"><strong>${d.openAlerts}</strong><span>Open alerts</span></div><div class="metric"><strong>${d.emailSuppressions??0}</strong><span>Blocked email addresses</span></div><div class="metric"><strong>${money(d.refunds.amountMinor)}</strong><span>Completed refunds</span></div></div><div class="split"><section class="card"><h2>Client Account Lookup</h2><form data-form="account-lookup" class="field"><label for="global-client">Exact client ID or registered email</label><input id="global-client" name="q" required><button>Open account</button></form></section><section class="card"><h2>Transaction Details</h2><form data-form="transaction-lookup" class="field"><label for="global-txn">Exact transaction ID</label><input id="global-txn" name="q" required><button>Open transaction</button></form></section></div><section class="card" style="margin-top:1rem"><h2>Recent staff events</h2>${eventTable(d.recentEvents)}</section>`}
function accountLookup(){return `${head('Client account lookup','Search an exact client ID or email, or find accounts by a contact or team member name.')}<section class="card lookup-card"><form data-form="account-lookup" class="lookup-form"><div class="field"><label for="account-lookup-query">Exact client ID or registered email</label><input id="account-lookup-query" name="q" autocomplete="off" required></div><button>Look up client</button></form></section><section class="card lookup-card" style="margin-top:1rem"><h2>Search by name</h2><form data-form="account-name-search" class="staff-search-grid"><div class="field"><label for="staff-search-first">First name</label><input id="staff-search-first" name="first" minlength="2" value="${esc(state.accountSearch.first)}"></div><div class="field"><label for="staff-search-last">Last name</label><input id="staff-search-last" name="last" minlength="2" value="${esc(state.accountSearch.last)}"></div><div class="field"><label for="staff-search-name">Full name</label><input id="staff-search-name" name="name" minlength="2" value="${esc(state.accountSearch.name)}"></div><button>Search names</button></form><p class="muted">You can fill either name field, both, or the full name field.</p>${state.accountMatches.length?`<div class="table-wrap"><table><thead><tr><th>Matching person</th><th>Account</th><th>Plan</th><th></th></tr></thead><tbody>${state.accountMatches.map(item=>`<tr><td>${esc(item.matchedName)}<br><small>${esc(item.matchedEmail)}</small></td><td>${esc(item.account.legalName)}</td><td>${esc(item.account.planId)}</td><td><button class="secondary" data-action="open-account" data-id="${esc(item.account.id)}">Open</button></td></tr>`).join('')}</tbody></table></div>`:''}</section>${state.account?accountDetail(state.account):''}`}

function accountDetail(d){state.sensitiveOpenedAt=Date.now();const a=d.account;return `<section class="card" style="margin-top:1rem"><div class="workspace-header"><div><p class="eyebrow">Client account</p><h2>${esc(a.legalName)}</h2><p>${esc(a.contactEmail)} · <span class="mono">${esc(a.id)}</span></p></div>${badge(a.closureStatus)}</div><div class="grid-3"><div><strong>Plan</strong><p>${esc(a.planId)}</p></div><div><strong>Billing reference</strong><p class="mono">${esc(a.providerCustomerId)}</p></div><div><strong>Jurisdiction</strong><p>${esc(a.region)}, ${esc(a.country)}</p></div></div><div class="actions">${a.closureStatus==='active'?`<button class="danger" data-action="close-account" data-id="${esc(a.id)}">Schedule account to be closed</button>`:''}${a.closureStatus==='scheduled'?`<button class="secondary" data-action="reopen-account" data-id="${a.id}">Undo closure</button>`:''}</div>${a.cancellation?`<section class="notice"><strong>Subscription cancellation: ${esc(a.cancellation.status)}</strong><p>Effective: ${date(a.cancellation.effectiveAt)} · Email: ${esc(a.cancellation.confirmationEmail)}${a.cancellation.financialReview?' · Financial reconciliation pending':''}</p>${['attention','retry_scheduled'].includes(a.cancellation.status)?`<button class="secondary" data-action="retry-cancellation" data-id="${esc(a.id)}">Retry cancellation after review</button>`:''}<p>Reopening restores account access, not billing.</p></section>`:''}<h3>Registered watchers</h3><div class="table-wrap"><table><thead><tr><th>Watcher</th><th>Masked URL</th><th>Recipients</th><th>Status</th><th></th></tr></thead><tbody>${d.watchers.map(w=>`<tr><td>${esc(w.name)}<br><span class="mono">${w.id}</span></td><td class="mono">${esc(w.config.url)}</td><td>${w.config.recipientTiers.flatMap(t=>t.recipients).map(r=>esc(r.destination)).join('<br>')}</td><td>${badge(w.status)}</td><td><div class="actions"><button class="secondary" data-action="watch-edit" data-id="${w.id}">Edit</button><button class="secondary" data-action="watch-status" data-id="${w.id}" data-status="${w.status==='active'?'paused':'active'}">${w.status==='active'?'Pause':'Resume'}</button><button class="danger" data-action="watch-delete" data-id="${w.id}">Delete</button></div></td></tr>`).join('')}</tbody></table></div><h3>Billing history</h3>${transactionTable(d.transactions)}<h3>Staff notes</h3><form data-form="note" data-account="${a.id}" class="field"><textarea name="body" required placeholder="Operational note; do not paste customer page content."></textarea><input name="reason" required placeholder="Reason for adding note"><button>Add staff note</button></form>${d.notes.map(n=>`<p><strong>${date(n.createdAt)}</strong> — ${esc(n.body)}</p>`).join('')}<h3>Staff event history</h3>${eventTable(d.events)}</section>${state.editWatcher?supportEditModal(state.editWatcher):''}`}
function supportEditModal(w){const methods=[['outage','Page outage'],['banned_phrase','Banned phrase'],['text_change','Text change'],['pixel_change','Screenshot pixels']];const intervals=[[604800,'Weekly'],[86400,'Daily'],[3600,'Hourly'],[900,'Every 15 minutes'],[120,'Every 2 minutes']];return `<div class="modal" role="dialog" aria-modal="true" aria-labelledby="support-edit-title"><form id="support-edit-form" class="modal-panel" data-id="${esc(w.id)}"><div class="workspace-header"><div><p class="eyebrow">Privacy-preserving support edit</p><h2 id="support-edit-title">Edit ${esc(w.name)}</h2><p class="muted">Sensitive values stay masked. Leave replacement fields blank to preserve them unchanged.</p></div><button type="button" class="secondary" data-action="close-watch-edit">Close</button></div><input type="hidden" name="configRevision" value="${Number(w.configRevision||1)}"><div class="form-grid"><div class="field"><label>Watcher name</label><input name="name" value="${esc(w.name)}" maxlength="120" required></div><div class="field"><label>Check frequency</label><select name="checkIntervalSeconds">${intervals.map(([value,label])=>`<option value="${value}" ${Number(w.config.checkIntervalSeconds)===value?'selected':''}>${label}</option>`).join('')}</select><small>The account plan is enforced by the server.</small></div><div class="field full"><label>Replacement URL</label><input name="replacementUrl" type="url" placeholder="Leave blank to keep ${esc(w.config.url)}"><small>The existing full URL is never returned to this console.</small></div><div class="field full"><label>Detection methods</label><div class="checks">${methods.map(([id,label])=>`<label class="check"><input type="checkbox" name="methods" value="${id}" ${w.config.methods.includes(id)?'checked':''}> ${label}</label>`).join('')}</div></div><div class="field"><label>Text threshold (%)</label><input name="textThresholdPercent" type="number" min="0" max="100" step="0.1" value="${Number(w.config.textThresholdPercent)}"></div><div class="field"><label>Pixel threshold (%)</label><input name="pixelThresholdPercent" type="number" min="0" max="100" step="0.1" value="${Number(w.config.pixelThresholdPercent)}"></div><div class="field"><label>All-clear consensus</label><input name="allClearThreshold" type="number" min="1" value="${Number(w.config.allClearThreshold)}"></div><div class="field"><label>Alert-received consensus</label><input name="alertReceivedThreshold" type="number" min="1" value="${Number(w.config.alertReceivedThreshold)}"></div><div class="field full"><h3>Escalation levels</h3>${w.config.recipientTiers.map((tier,index)=>`<section class="recipient-tier card" data-support-tier data-id="${esc(tier.id)}"><strong>Level ${index+1}: ${esc(tier.name)}</strong><div class="form-grid"><div class="field"><label>Wait before next level (minutes)</label><input name="tierDelay" type="number" min="1" max="10080" value="${Number(tier.delayMinutes)}"></div><div class="field"><label>Required acknowledgements</label><input name="tierRequired" type="number" min="1" value="${Number(tier.requiredAcknowledgements)}"></div></div>${tier.recipients.map(recipient=>`<div class="field" data-support-recipient data-id="${esc(recipient.id)}"><label>Replace ${esc(recipient.name)} ${esc(recipient.channel)} destination</label><input name="recipientReplacement" placeholder="Leave blank to keep ${esc(recipient.destination)}"><small>Current masked value: ${esc(recipient.destination)}</small></div>`).join('')}</section>`).join('')}</div><div class="field full"><label>Staff reason</label><textarea name="reason" minlength="5" required placeholder="Why this support change is authorized"></textarea></div></div><div class="form-actions"><button type="button" class="secondary" data-action="close-watch-edit">Cancel</button><button>Save support edit</button></div></form></div>`}
function transactionLookup(){return `${head('Transaction details','Search an exact transaction ID. Payment references remain masked.')}<section class="card lookup-card"><form data-form="transaction-lookup" class="lookup-form"><div class="field"><label for="transaction-lookup-query">Transaction ID</label><input id="transaction-lookup-query" name="q" autocomplete="off" required></div><button>Look up transaction</button></form></section>${state.transaction?transactionDetail(state.transaction):''}`}
function transactionDetail(d){state.sensitiveOpenedAt=Date.now();const t=d.transaction;return `<section class="card" style="margin-top:1rem"><div class="workspace-header"><div><p class="eyebrow">Transaction</p><h2 class="mono">${t.id}</h2><p>Client <button class="secondary" data-action="open-account" data-id="${t.accountId}">${esc(d.account?.legalName||t.accountId)}</button></p></div>${badge(t.status)}</div><div class="grid-3"><div><strong>Amount</strong><p>${money(t.amountMinor,t.currency)}</p></div><div><strong>Tax</strong><p>${t.taxMinor==null?'Pending':money(t.taxMinor,t.currency)}</p></div><div><strong>Date</strong><p>${date(t.createdAt)}</p></div><div><strong>Payment reference</strong><p class="mono">${esc(t.paymentReference)}</p></div><div><strong>Provider customer</strong><p class="mono">${esc(t.providerCustomerId)}</p></div><div><strong>Outcome reason</strong><p>${esc(t.outcomeReason||'—')}</p></div></div><div class="actions">${['failed','declined','retry_scheduled'].includes(t.status)?`<button data-action="retry-transaction" data-id="${t.id}">Retry transaction</button>`:''}${t.status==='completed'?`<button class="danger" data-action="refund" data-id="${t.id}" data-max="${t.amountMinor}">Schedule refund</button>`:''}</div><h3>Refunds</h3>${d.refunds.length?d.refunds.map(r=>`<p>${badge(r.status)} ${money(r.amountMinor,r.currency)} — ${esc(r.reason)}</p>`).join(''):'<p class="muted">No refunds.</p>'}<h3>Transaction staff history</h3>${eventTable(d.events)}</section>`}
function closureView(){return `${head('Account closures and erasure','Undo is available during the grace period. Once erasure starts, unfinished identity, asset and email stages remain visible here.')}<div class="table-wrap"><table><thead><tr><th>Account</th><th>Contact</th><th>Scheduled</th><th>Delete after</th><th>Progress</th><th>Action</th></tr></thead><tbody>${state.closures.map(a=>`<tr><td>${esc(a.legalName)}<br><span class="mono">${esc(a.id)}</span></td><td>${esc(a.contactEmail)}</td><td>${date(a.scheduledAt)}</td><td>${date(a.deleteAfter)}</td><td>${badge(a.phase||'scheduled')}${a.cancellation?`<p>Subscription: ${esc(a.cancellation.status)}</p>`:''}${a.blockedReason?`<p>${a.blockedReason==='provider_subscription_cancellation_pending'?'Waiting for confirmed subscription cancellation.':'Waiting for billing reconciliation.'}</p>`:''}${a.identityStatus?`<p>Identity: ${esc(a.identityStatus.replaceAll('_',' '))}</p>`:''}${a.notificationState?`<p>Email: ${esc(a.notificationState.replaceAll('_',' '))}</p>`:''}${a.requiresReview?'<p>Owner review required. Check the erasure runbook before retrying.</p>':''}</td><td>${a.canUndo?`<button class="secondary" data-action="reopen-account" data-id="${esc(a.id)}">Undo closure</button>`:'<span>Erasure cannot be undone.</span>'}</td></tr>`).join('')}</tbody></table></div>`}
function refundView(){return `${head('Refund register','Aggregate and granular refund activity.')}<div class="table-wrap"><table><thead><tr><th>Refund</th><th>Account</th><th>Transaction</th><th>Amount</th><th>Status</th></tr></thead><tbody>${state.refunds.map(r=>`<tr><td class="mono">${r.id}</td><td><button class="secondary" data-action="open-account" data-id="${r.accountId}">${esc(r.account?.legalName||r.accountId)}</button></td><td><button class="secondary" data-action="open-transaction" data-id="${r.transactionId}">${r.transactionId}</button></td><td>${money(r.amountMinor,r.currency)}</td><td>${badge(r.status)}</td></tr>`).join('')}</tbody></table></div>`}
function emailSuppressionView(){
  const owner=state.stewardRole==='owner';
  const add=owner?'<section class="card"><h2>Add an address</h2><form data-form="email-suppression-add" class="field"><label for="suppression-email">Email address</label><input id="suppression-email" name="email" type="email" autocomplete="off" required><label for="suppression-reason">Staff reason</label><textarea id="suppression-reason" name="reason" minlength="5" required></textarea><button>Block customer email</button></form></section>':'';
  return `${head('Email block list','Customer alerts and invitations use these platform-wide recipient blocks.')}<section class="card suppression-intro"><strong>Recipient consent takes precedence.</strong><p class="muted">Adding an address stops queued customer retries and future customer alert and invitation email. Removing one permits future customer email without replaying blocked notifications. Security and account-erasure notices use a separate audited operational delivery path; provider bounce and complaint restrictions still apply.</p>${owner?'':'<p class="muted">Only the platform owner can add or remove staff-managed blocks.</p>'}</section><div class="split suppression-tools">${add}<section class="card"><h2>Search the block list</h2><form data-form="email-suppression-search" class="field"><label for="suppression-search">Partial email address</label><input id="suppression-search" name="q" value="${esc(state.emailSuppressionQuery)}" autocomplete="off"><div class="actions"><button>Search</button>${state.emailSuppressionQuery?'<button type="button" class="secondary" data-action="clear-suppression-search">Clear</button>':''}</div></form></section></div><section class="card suppression-register"><div class="workspace-header"><div><h2>Blocked addresses</h2><p class="muted">${state.emailSuppressions.length} matching address${state.emailSuppressions.length===1?'':'es'}</p></div></div>${state.emailSuppressions.length?`<div class="table-wrap"><table><thead><tr><th>Email address</th><th>Source</th><th>Blocked</th><th>Reason</th>${owner?'<th>Action</th>':''}</tr></thead><tbody>${state.emailSuppressions.map(item=>`<tr><td>${esc(item.email)}</td><td>${badge(item.source)}</td><td>${date(item.createdAt)}</td><td>${esc(item.reason||'—')}</td>${owner?`<td><button class="secondary" data-action="remove-email-suppression" data-id="${esc(item.id)}">Remove block</button></td>`:''}</tr>`).join('')}</tbody></table></div>`:'<div class="empty">No blocked email addresses match this search.</div>'}</section>`;
}
function managerView(){const m=state.manager;return `${head('Steward Manager','Platform owner access · invitations, staff access and audit review.')}<section class="card"><h2>Invite a steward</h2><form data-form="steward-invite" class="lookup-form"><div class="field"><label for="staff-invite-email">Work email</label><input id="staff-invite-email" type="email" name="email" required></div><button>Send invitation</button></form></section><section class="card" style="margin-top:1rem"><h2>Steward accounts</h2><button class="secondary" data-action="staff-activity" data-id="${esc(m.owner.actorId)}">View owner activity</button><div class="table-wrap"><table><thead><tr><th>Email</th><th>State</th><th>Invited</th><th>Access</th></tr></thead><tbody>${m.users.map(user=>`<tr><td>${esc(user.email)}</td><td>${badge(user.status)}</td><td>${date(user.invitedAt)}</td><td class="actions"><button class="secondary" data-action="staff-activity" data-id="${esc(user.actorId||'')}" ${user.actorId?'':'disabled'}>Activity</button>${user.status==='active'?`<button class="secondary" data-action="staff-status" data-email="${esc(user.email)}" data-status="disabled">Disable</button>`:user.status==='disabled'?`<button class="secondary" data-action="staff-status" data-email="${esc(user.email)}" data-status="active">Enable</button>`:''}${user.status!=='deleted'?`<button class="danger" data-action="staff-status" data-email="${esc(user.email)}" data-status="deleted">Delete</button>`:''}</td></tr>`).join('')}</tbody></table></div></section><section class="card" style="margin-top:1rem"><h2>Suspicious activity thresholds</h2><p class="muted">An email goes to admin@redcloversoftware.ca when an individual steward exceeds a count within its time window, or schedules a refund larger than the single refund limit.</p><form data-form="steward-limits" class="staff-search-grid">${[['searchCount','Account searches','searchWindowMinutes','Minutes'],['closureCount','Account closures','closureWindowMinutes','Minutes'],['refundCount','Refunds','refundWindowMinutes','Minutes']].map(([count,label,window,windowLabel])=>`<div class="field"><label>${label} before alert<input name="${count}" type="number" min="1" required value="${Number(m.limits[count])}"></label></div><div class="field"><label>${windowLabel} per window<input name="${window}" type="number" min="1" max="1440" required value="${Number(m.limits[window])}"></label></div>`).join('')}<div class="field"><label>Single refund limit (refund currency)<input name="singleRefundDollars" type="number" step="0.01" min="0.01" required value="${(m.limits.singleRefundMinor/100).toFixed(2)}"></label></div><button>Save thresholds</button></form></section><section class="card" style="margin-top:1rem"><h2>Activity log ${state.selectedStaff?`· ${esc(state.selectedStaff)}`:''}</h2>${state.selectedStaff?`<div class="table-wrap"><table><thead><tr><th>Time</th><th>Request</th><th>Outcome</th><th>Request ID</th></tr></thead><tbody>${state.staffActivity.map(item=>`<tr><td>${date(item.startedAt)}</td><td class="mono">${esc(item.method)} ${esc(item.path)}</td><td>${badge(item.status)} ${Number(item.statusCode)||''}</td><td class="mono">${esc(item.requestId)}<details><summary>Request context</summary><p>IP fingerprint: ${esc(item.ipHash||'—')}<br>Search fingerprint: ${esc(item.queryHash||'—')}<br>Browser: ${esc(item.userAgent||'—')}</p>${item.details&&Object.keys(item.details).length?`<pre>${esc(JSON.stringify(item.details,null,2))}</pre>`:''}${item.actions?.length?item.actions.map(action=>`<p><strong>${esc(action.action)}</strong> · ${esc(action.reason||'—')}</p><pre>${esc(JSON.stringify({accountId:action.accountId,transactionId:action.transactionId,targetId:action.targetId,metadata:action.metadata},null,2))}</pre>`).join(''):''}</details></td></tr>`).join('')}</tbody></table></div>${state.staffActivityNext?'<button class="secondary" data-action="staff-activity-more">Load older activity</button>':''}`:'<p class="muted">Choose Activity for a steward account above.</p>'}</section>`}
function transactionTable(items){return `<div class="table-wrap"><table><thead><tr><th>ID</th><th>Date</th><th>Amount</th><th>Status</th></tr></thead><tbody>${items.map(t=>`<tr><td><button class="secondary mono" data-action="open-transaction" data-id="${t.id}">${t.id}</button></td><td>${date(t.createdAt)}</td><td>${money(t.amountMinor,t.currency)}</td><td>${badge(t.status)}</td></tr>`).join('')}</tbody></table></div>`}
function eventTable(items){return `<div class="table-wrap"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Reason</th></tr></thead><tbody>${items.map(e=>`<tr><td>${date(e.at)}</td><td class="mono">${esc(e.actorId)}</td><td>${esc(e.action)}</td><td>${esc(e.reason||'—')}</td></tr>`).join('')}</tbody></table></div>`}
function bind(){
  $$('form').forEach(form=>form.addEventListener('submit',()=>clearFormErrors(form)));
  $('[data-form="account-name-search"]')?.addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const fields=Object.fromEntries(new FormData(form));if(!Object.values(fields).some(value=>String(value).trim())){showFormError(form,'Enter a first name, last name, or full name.');return}try{const params=new URLSearchParams(fields);const response=await api(`/api/steward/accounts/search?${params}`);state.accountSearch=fields;state.accountMatches=response.results;render();if(!response.results.length)toast('No matching accounts.')}catch(error){showFormError(form,error.message)}});
  $('[data-form="steward-invite"]')?.addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;try{await api('/api/steward/manager/users',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});toast('Invitation sent.');await render()}catch(error){showFormError(form,error.message)}});
  $('[data-form="steward-limits"]')?.addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const data=Object.fromEntries(new FormData(form));const body={};for(const key of ['searchCount','searchWindowMinutes','closureCount','closureWindowMinutes','refundCount','refundWindowMinutes'])body[key]=Number(data[key]);body.singleRefundMinor=Math.round(Number(data.singleRefundDollars)*100);try{await api('/api/steward/manager/limits',{method:'PUT',body:JSON.stringify(body)});toast('Thresholds saved.');await render()}catch(error){showFormError(form,error.message)}});
  $$('[data-action="staff-status"]').forEach(button=>button.onclick=async()=>{const decision=await requestStaffConfirmation({title:`${button.dataset.status} this steward?`,copy:'This changes their access to the staff console. Record why you are making the change.',confirmLabel:'Confirm'});if(!decision)return;try{await api(`/api/steward/manager/users/${encodeURIComponent(button.dataset.email)}`,{method:'PATCH',body:JSON.stringify({status:button.dataset.status,reason:decision.reason})});toast('Steward account updated.');await render()}catch(error){toast(error.message)}});
  $$('[data-action="staff-activity"]').forEach(button=>button.onclick=async()=>{try{const response=await api(`/api/steward/manager/users/${encodeURIComponent(button.dataset.id)}/activity`);state.selectedStaff=button.dataset.id;state.staffActivity=response.events;state.staffActivityNext=response.nextBefore;render()}catch(error){toast(error.message)}});
  $('[data-action="staff-activity-more"]')?.addEventListener('click',async()=>{try{const response=await api(`/api/steward/manager/users/${encodeURIComponent(state.selectedStaff)}/activity?before=${encodeURIComponent(state.staffActivityNext)}`);state.staffActivity.push(...response.events);state.staffActivityNext=response.nextBefore;render()}catch(error){toast(error.message)}});
  $$('[data-form="account-lookup"]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{state.account=await api(`/api/steward/accounts/lookup?q=${encodeURIComponent(new FormData(f).get('q'))}`);state.view='accounts';updateRoute('accounts',{account:state.account.account.id});render()}catch(x){showFormError(f,x.message)}});
  $$('[data-form="transaction-lookup"]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{state.transaction=await api(`/api/steward/transactions/lookup?q=${encodeURIComponent(new FormData(f).get('q'))}`);state.view='transactions';updateRoute('transactions',{transaction:state.transaction.transaction.id});render()}catch(x){showFormError(f,x.message)}});
  $('[data-form="note"]')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;const b=Object.fromEntries(new FormData(form));try{await api(`/api/steward/accounts/${form.dataset.account}/notes`,{method:'POST',body:JSON.stringify(b)});state.account=await api(`/api/steward/accounts/${form.dataset.account}`);render();}catch(error){showFormError(form,error.message)}});
  $$('[data-action="close-account"]').forEach(b=>b.onclick=()=>staffPost(`/api/steward/accounts/${b.dataset.id}/close`,'account closure'));
  $$('[data-action="retry-cancellation"]').forEach(b=>b.onclick=()=>staffPost(`/api/steward/accounts/${b.dataset.id}/retry-cancellation`,'retry subscription cancellation after review'));
  $$('[data-action="reopen-account"]').forEach(b=>b.onclick=()=>staffPost(`/api/steward/accounts/${b.dataset.id}/reopen`,'closure cancellation'));
  $$('[data-action="watch-edit"]').forEach(b=>b.onclick=()=>{state.editWatcher=structuredClone(state.account.watchers.find(w=>w.id===b.dataset.id));updateRoute('accounts',{account:state.account.account.id,modal:'watcher-edit',watcher:b.dataset.id});render()});
  $$('[data-action="close-watch-edit"]').forEach(b=>b.onclick=()=>closeSupportDialog());
  $('#support-edit-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;const body={name:form.name.value,configRevision:Number(form.configRevision.value),replacementUrl:form.replacementUrl.value.trim(),checkIntervalSeconds:Number(form.checkIntervalSeconds.value),methods:new FormData(form).getAll('methods'),textThresholdPercent:Number(form.textThresholdPercent.value),pixelThresholdPercent:Number(form.pixelThresholdPercent.value),allClearThreshold:Number(form.allClearThreshold.value),alertReceivedThreshold:Number(form.alertReceivedThreshold.value),reason:form.reason.value.trim(),tiers:$$('[data-support-tier]',form).map(node=>({id:node.dataset.id,delayMinutes:Number($('[name="tierDelay"]',node).value),requiredAcknowledgements:Number($('[name="tierRequired"]',node).value)})),recipientReplacements:$$('[data-support-recipient]',form).map(node=>({id:node.dataset.id,destination:$('[name="recipientReplacement"]',node).value.trim()}))};try{await api(`/api/steward/watchers/${form.dataset.id}`,{method:'PATCH',body:JSON.stringify(body)});state.editWatcher=null;state.account=await api(`/api/steward/accounts/${state.account.account.id}`);updateRoute('accounts',{account:state.account.account.id},true);toast('Support edit recorded.');render()}catch(error){showFormError(form,error.message)}});
  $$('[data-action="watch-status"]').forEach(b=>b.onclick=()=>staffPost(`/api/steward/watchers/${b.dataset.id}/status`,'watcher status change',{status:b.dataset.status}));
  $$('[data-action="watch-delete"]').forEach(b=>b.onclick=()=>staffDelete(`/api/steward/watchers/${b.dataset.id}`,'watcher deletion'));
  $$('[data-action="retry-transaction"]').forEach(b=>b.onclick=()=>staffPost(`/api/steward/transactions/${b.dataset.id}/retry`,'billing retry'));
  $$('[data-action="refund"]').forEach(b=>b.onclick=async()=>{const decision=await requestStaffConfirmation({title:'Schedule this refund?',copy:`Confirm an amount up to ${b.dataset.max} cents and record why this refund is authorized.`,amountMax:Number(b.dataset.max),confirmLabel:'Schedule refund'});if(!decision)return;await api(`/api/steward/transactions/${b.dataset.id}/refund`,{method:'POST',body:JSON.stringify({reason:decision.reason,amountMinor:decision.amount})});toast('Refund scheduled.');await render();});
  $$('[data-action="open-account"]').forEach(b=>b.onclick=async()=>{state.account=await api(`/api/steward/accounts/${b.dataset.id}`);state.transaction=null;state.view='accounts';updateRoute('accounts',{account:b.dataset.id});render()});
  $$('[data-action="open-transaction"]').forEach(b=>b.onclick=async()=>{state.transaction=await api(`/api/steward/transactions/${b.dataset.id}`);state.account=null;state.view='transactions';updateRoute('transactions',{transaction:b.dataset.id});render()});
  $('[data-form="email-suppression-add"]')?.addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const body=Object.fromEntries(new FormData(form));try{await api('/api/steward/email-suppressions',{method:'POST',body:JSON.stringify(body)});state.dashboard=null;toast('Customer email address blocked platform-wide.');await render()}catch(error){showFormError(form,error.message)}});
  $('[data-form="email-suppression-search"]')?.addEventListener('submit',event=>{event.preventDefault();state.emailSuppressionQuery=String(new FormData(event.currentTarget).get('q')||'').trim();updateRoute('email-suppressions',state.emailSuppressionQuery?{q:state.emailSuppressionQuery}:{});void render()});
  $('[data-action="clear-suppression-search"]')?.addEventListener('click',()=>{state.emailSuppressionQuery='';updateRoute('email-suppressions',{});void render()});
  $$('[data-action="remove-email-suppression"]').forEach(button=>button.onclick=async()=>{const decision=await requestStaffConfirmation({title:'Remove this email block?',copy:'Future customer alert and invitation email may be sent to this address again. Previously blocked notifications will not be replayed.',confirmLabel:'Remove block'});if(!decision)return;try{await api(`/api/steward/email-suppressions/${encodeURIComponent(button.dataset.id)}`,{method:'DELETE',body:JSON.stringify({reason:decision.reason})});state.dashboard=null;toast('Email block removed.');await render()}catch(error){toast(error.message)}});
}
async function staffPost(url,action,extra={}){const decision=await requestStaffConfirmation({title:`Confirm ${action}?`,copy:'Review the affected record and provide an auditable staff reason before continuing.',confirmLabel:'Confirm action'});if(!decision)return;await api(url,{method:'POST',body:JSON.stringify({...extra,reason:decision.reason})});toast('Staff action recorded.');if(state.account)state.account=await api(`/api/steward/accounts/${state.account.account.id}`);await render()}
async function staffDelete(url,action){const decision=await requestStaffConfirmation({title:`Confirm ${action}?`,copy:'This destructive action cannot be undone from the steward console. Record why it is authorized.',confirmLabel:'Delete watcher'});if(!decision)return;await api(url,{method:'DELETE',body:JSON.stringify({reason:decision.reason})});toast('Watcher deleted.');state.account=await api(`/api/steward/accounts/${state.account.account.id}`);render()}
function clearIdleWarning(){idleWarning?.remove();idleWarning=null;}
function jettison(){cancelStaffConfirmation?.();clearIdleWarning();state.account=null;state.transaction=null;state.editWatcher=null;state.sensitiveOpenedAt=0}
function checkIdleTimeout(){
  if(!state.sensitiveOpenedAt){clearIdleWarning();return;}
  const remaining=IDLE_LIMIT_MS-(Date.now()-state.lastActivity);
  if(remaining<=0){jettison();state.view='dashboard';updateRoute('dashboard',{},true);void render().then(()=>{const notice=document.createElement('div');notice.className='notice warn';notice.tabIndex=-1;notice.setAttribute('role','alert');notice.textContent='Client view closed after 30 minutes idle. Unsaved client notes and edits were cleared. Open the client record again to continue.';$('#workspace')?.prepend(notice);notice.focus();});return;}
  if(remaining>IDLE_WARNING_MS)return;
  if(!idleWarning){idleWarning=document.createElement('aside');idleWarning.className='card steward-idle-warning';idleWarning.setAttribute('aria-label','Client view idle warning');idleWarning.innerHTML='<p role="alert"><strong>Your client view is about to close.</strong> Choose Keep client view open to allow another 30 minutes. Unsaved notes and edits are cleared when the idle time expires.</p><p data-idle-countdown aria-live="off"></p><button type="button" data-idle-extend>Keep client view open</button>';idleWarning.querySelector('[data-idle-extend]').onclick=()=>{state.lastActivity=Date.now();const returnTo=document.activeElement;clearIdleWarning();if(returnTo?.closest('.steward-idle-warning')){const modal=document.querySelector('body > .modal[role="dialog"]');(modal?.querySelector('[data-modal-initial-focus]')||$('#workspace'))?.focus();}toast('Client view extended for another 30 minutes.');};}
  const parent=$$('body > .modal[role="dialog"]').at(-1)?.querySelector('.modal-panel')||$('#workspace');if(parent&&!parent.contains(idleWarning))parent.prepend(idleWarning);
  idleWarning.querySelector('[data-idle-countdown]').textContent=`Closes in ${Math.max(1,Math.ceil(remaining/1000))} seconds.`;
}
for(const event of ['pointerdown','keydown','scroll','touchstart'])addEventListener(event,()=>{if(!idleWarning)state.lastActivity=Date.now();},{passive:true});
setInterval(checkIdleTimeout,1000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')checkIdleTimeout();});
document.addEventListener('keydown',(event)=>{const modal=document.querySelector('body > .modal[role="dialog"]');if(!modal)return;if(event.key==='Escape'){event.preventDefault();const cancel=modal.querySelector('[data-staff-cancel]');if(cancel)cancel.click();else closeSupportDialog();return;}if(event.key!=='Tab')return;const focusable=dialogFocusable(modal);if(!focusable.length){event.preventDefault();modal.focus();return;}const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}});
$('#enter').onclick=()=>void enterStewardConsole({interactive:true});
addEventListener('popstate',()=>{if(consoleReady)void hydrateLocation()});
addEventListener('pageshow',()=>{if(!consoleReady&&auth?.authenticated)void enterStewardConsole()});
void portalAuth().then(session=>{if(session.authenticated)return enterStewardConsole();syncAuthChrome()}).catch(showEntryError);
